def el(tag,**attrs):
    prefix,name=tag.split(':');n=E.Element('{'+NS[prefix]+'}'+name)
    for k,v in attrs.items():
        if ':' in k: p,t=k.split(':');n.set('{'+NS[p]+'}'+t,str(v))
        else:n.set(k,str(v))
    return n
root=E.Element('{'+NS['w']+'}document',nsmap=NS); body=E.SubElement(root,'{'+NS['w']+'}body')
rels=E.Element('Relationships',nsmap={None:'http://schemas.openxmlformats.org/package/2006/relationships'})
for id,typ,target in [('styles','styles','styles.xml'),('footer','footer','footer1.xml'),('settings','settings','settings.xml')]:E.SubElement(rels,'Relationship',Id=id,Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/'+typ,Target=target)
images={}; pages=[]; md=[]; table_no=0; fig_no=0
def paragraph(t='',style='Normal',parent=body,align=None,bold=False,size=None):
    p=el('w:p');pr=el('w:pPr');pr.append(el('w:pStyle',**{'w:val':style}))
    if align:pr.append(el('w:jc',**{'w:val':align}))
    p.append(pr);r=el('w:r')
    rp=el('w:rPr')
    if bold:rp.append(el('w:b'))
    if size:rp.append(el('w:sz',**{'w:val':size}))
    r.append(rp)
    for i,line in enumerate(t.split('\n')):
        if i:r.append(el('w:br'))
        tx=el('w:t');tx.set('{http://www.w3.org/XML/1998/namespace}space','preserve');tx.text=line;r.append(tx)
    p.append(r);parent.append(p)
    if parent is body:md.append(t+'\n')
    return p
def p(t):return paragraph(t)
def h(t):return paragraph(t,'Heading2')
def page(title):
    if pages:
        n=paragraph();n.find('{'+NS['w']+'}pPr').append(el('w:pageBreakBefore'))
        # The heading shares the break paragraph, preventing a leading blank line.
        body.remove(n)
        n=paragraph(title,'Heading1');n.find('{'+NS['w']+'}pPr').append(el('w:pageBreakBefore'))
    else:paragraph(title,'Heading1')
    pages.append((len(pages)+1,title));md.append('\n# '+title+'\n')
def table(headers,rows,caption,widths=None):
    global table_no
    table_no+=1;tab=el('w:tbl');pr=el('w:tblPr');pr.append(el('w:tblW',**{'w:w':'9638','w:type':'dxa'}));pr.append(el('w:tblLayout',**{'w:type':'fixed'}));
    borders=el('w:tblBorders')
    for side in ['top','left','bottom','right','insideH','insideV']:borders.append(el('w:'+side,**{'w:val':'single','w:sz':'4','w:color':'CBD5E1'}))
    pr.append(borders);tab.append(pr)
    widths=widths or [int(9638/len(headers))]*len(headers);grid=el('w:tblGrid')
    for w in widths:grid.append(el('w:gridCol',**{'w:w':w}))
    tab.append(grid)
    for idx,row in enumerate([headers]+rows):
        tr=el('w:tr');trp=el('w:trPr');trp.append(el('w:cantSplit'))
        if idx==0:trp.append(el('w:tblHeader'))
        tr.append(trp)
        for j,txt in enumerate(row):
            tc=el('w:tc');tcp=el('w:tcPr');tcp.append(el('w:tcW',**{'w:w':widths[j],'w:type':'dxa'}));tcp.append(el('w:shd',**{'w:fill':'E2E8F0' if idx==0 else 'F8FAFC' if idx%2 else 'FFFFFF'}));m=el('w:tcMar')
            for side in ['top','bottom','left','right']:m.append(el('w:'+side,**{'w:w':'85','w:type':'dxa'}))
            tcp.append(m);tc.append(tcp);paragraph(str(txt),'TableText',tc,bold=idx==0);tr.append(tc)
        tab.append(tr)
    body.append(tab);paragraph(f'Таблица {table_no} — {caption}','Caption')
    md.append('| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(str(x).replace('\n','; ') for x in row)+' |' for row in rows)+'\n')
def figure(name,caption,maxheight=213):
    global fig_no
    fig_no+=1;path=next((BASE/'diagrams').glob(name+'*.png'));im=Image.open(path); iw,ih=im.size
    w=min(170,maxheight*iw/ih);hh=w*ih/iw;cx=int(w*36000);cy=int(hh*36000);rid='image'+str(fig_no)
    images[rid]=(path,cx,cy);E.SubElement(rels,'Relationship',Id=rid,Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/image',Target='media/'+path.name)
    pp=paragraph('',align='center');r=el('w:r');dr=el('w:drawing');inline=el('wp:inline',distT='0',distB='0',distL='0',distR='0');inline.append(el('wp:extent',cx=cx,cy=cy));inline.append(el('wp:docPr',id=fig_no,name=caption,descr=caption));graphic=el('a:graphic');gd=el('a:graphicData',uri=NS['pic']);pic=el('pic:pic');nv=el('pic:nvPicPr');nv.append(el('pic:cNvPr',id=fig_no,name=path.name));nv.append(el('pic:cNvPicPr'));pic.append(nv);bf=el('pic:blipFill');bf.append(el('a:blip',**{'r:embed':rid}));stretch=el('a:stretch');stretch.append(el('a:fillRect'));bf.append(stretch);pic.append(bf);sp=el('pic:spPr');xf=el('a:xfrm');xf.append(el('a:off',x='0',y='0'));xf.append(el('a:ext',cx=cx,cy=cy));sp.append(xf);geom=el('a:prstGeom',prst='rect');geom.append(el('a:avLst'));sp.append(geom);pic.append(sp);gd.append(pic);graphic.append(gd);inline.append(graphic);dr.append(inline);r.append(dr);pp.append(r)
    paragraph(f'Рисунок {fig_no} — {caption}','Caption');md.append(f'![{caption}](../diagrams/{path.name})\n')

